        'description' => <<<'HTML'
<p>Walk into a bank branch, a clinic reception or a school office in Kathmandu and you'll often find a ThinkCentre. The Neo 50a Gen 5 is the current all-in-one version. Everything lives behind a 23.8-inch screen, so there's no tower on the floor collecting dust and no cables for staff to trip over. It is listed at <strong>Rs 1,28,499</strong>.</p>
<p>Inside is an Intel <strong>Core i5-13420H</strong> (8 cores, 12 threads, up to 4.6GHz) with <strong>16GB of DDR5-5200</strong> and a 512GB Gen 4 SSD. That's plenty for accounting software, billing systems, Office, browser-based ERPs and video calls running at the same time. The Full HD IPS panel refreshes at 100Hz, covers 99% sRGB and is anti-glare, low-blue-light and flicker-free, which matters when someone stares at it for eight hours.</p>
<p>The 5MP camera and 3W × 2 Harman speakers handle meetings without a separate webcam. The port selection is properly office-friendly: Ethernet, 10Gbps USB-A and USB-C, two USB 2.0 ports for a barcode scanner or printer, and <strong>HDMI-in</strong>, so the screen can double as a monitor for a laptop. A wireless keyboard is included.</p>
<p>For home use with a slightly warmer design, compare it with the <a href="/products/lenovo-ideacentre-aio-24irh9-i5-13420h">IdeaCentre AIO 24IRH9</a>, which has the same chip.</p>
