<p>The specification is solid for the money: a 13th-gen <strong>Core i5-13420H</strong> (8 cores, up to 4.6GHz), <strong>16GB DDR5-5200</strong> and a 512GB PCIe 4.0 SSD, so it boots in seconds and doesn't choke when the kids open thirty tabs. The 23.8-inch IPS screen is anti-glare, covers 99% of sRGB and runs at 100Hz, which makes scrolling and light games feel smoother than a typical 60Hz office monitor.</p>
<p>The 5MP <strong>IR camera</strong> supports Windows Hello face login, so nobody has to remember a password. Wi-Fi 6 and Bluetooth 5.1 cover wireless, and Ethernet is there if your ISP router is nearby. An HDMI-in port lets you plug in a laptop or set-top box and use it as a second screen.</p>
