        'description' => <<<'HTML'
<p>The Aspire Lite 15 is Acer's plain-looking 15.6-inch workhorse, and our partner shop stocks three versions of the AL15-72P. All use 13th-gen Intel H-series processors, which are much faster than the U-series chips in most budget laptops, with a 15.6-inch FHD IPS anti-glare screen, a 58Wh battery and a Light Silver aluminium-look body.</p>
<ul>
<li><strong>Core i5-13500H, 8GB, 512GB – Rs 96,500.</strong> 12 cores, 16 threads, up to 4.7GHz. This is the pick of the range.</li>
<li><strong>Core i5-13420H, 8GB, 512GB – Rs 97,000.</strong> 8 cores, 12 threads. Slower than the 13500H yet costs more. Only buy it if the 13500H is out of stock.</li>
<li><strong>Core i7-13620H, 16GB – Rs 1,34,999.</strong> 10 cores, 16 threads, up to 4.9GHz. Our partner shop’s details list a 1TB SSD while the title says 512GB, so confirm when ordering.</li>
</ul>
<p>Everything runs on Intel UHD integrated graphics, so these are productivity laptops: Excel models, ERP and accounting software, programming, browser-heavy work. They're not for gaming. Ports include USB-C, USB-A and HDMI. At 1.8 kg it's a laptop for home and office more than daily commuting.</p>
<p>The 8GB models are the weak point. Memory runs out quickly with modern browsers, so plan to add a stick, or step up to the 16GB <a href="/products/acer-aspire-lite-15-al15-42p-ryzen-5-7430u">Aspire Lite 15 with Ryzen 5 7430U</a>.</p>
