        'description' => <<<'HTML'
<p>If you have exactly one lakh to spend and want a laptop that won't feel slow in two years, the Aspire Lite 15 AL15-42P is a strong candidate. It is listed at <strong>Rs 99,999</strong>, and it ships with <strong>16GB of RAM</strong>. That's double the 8GB most laptops at this price come with, and it's what keeps a busy browser, Teams and Excel running smoothly together.</p>
<p>The <strong>Ryzen 5 7430U</strong> has 6 cores and 12 threads (up to 4.3GHz), so it's faster than the 4-core chips around it. The 16GB DDR4-3200 is <strong>upgradeable to 32GB</strong>, and the 512GB SSD can be expanded. You get a full-size keyboard with number pad, Windows 11, a 15.6-inch FHD IPS display and, unusually, an <strong>Ethernet port</strong> alongside USB-C, USB-A and HDMI. It weighs 1.59 kg.</p>
<p>The battery is the compromise. It's only 36Wh, so expect a few hours of real use rather than a full day. The screen is a basic 250-nit, 45% NTSC panel, fine for documents but dull for photos. If battery life matters more to you than memory, the <a href="/products/acer-aspire-lite-14-al14-45p-ryzen-3-5400u">Aspire Lite 14 AL14-45P</a> has a 58Wh battery.</p>
