<p>The Aspire 3 A325-42 is a plain-looking laptop with a strong processor inside. Its <strong>Ryzen 7 7730U</strong> has 8 cores and 16 threads with a 4.5GHz boost. That's real multitasking muscle for coding, large spreadsheets, research software or the odd video export, at a price where most laptops have 4-core chips. The price is <strong>Rs 1,07,000</strong>.</p>
