<p>The Aspire 7 is a laptop for people who want to game a bit without carrying something that looks like a gaming laptop. It has a quiet, grown-up design, an <strong>RTX 3050 6GB</strong>, and a <strong>144Hz</strong> 15.6-inch screen. It is listed at <strong>Rs 1,57,499</strong>.</p>
<p>The CPU is Intel's <strong>Core 7 240H</strong>, a 10-core, 16-thread chip that boosts to 5.2GHz, quick for work and study software. The RTX 3050 here runs at a modest <strong>60W TGP</strong>, though, so it's slower than the 95W version in the <a href="/products/lenovo-loq-15-15ahp9-2024-ryzen-7-7445hs">Lenovo LOQ 15AHP9</a>. Think esports titles at high frame rates and older AAA games at medium settings rather than new releases at high.</p>
<p>Memory is a single 16GB DDR4 stick in one of <strong>two slots</strong>, so adding a second stick for dual channel is cheap and worthwhile. The 512GB SSD can be upgraded to 1TB. The 144Hz panel is smooth but only 45% NTSC, so it's not for colour work. It weighs just under 2 kg with a 54Wh battery.</p>
<p>Who should buy it? A student or office worker who plays after hours and values a subtle design. If gaming is the priority, the LOQ is the faster choice for less money.</p>
