<p>The Nitro Lite is Acer's attempt at a gaming laptop that's easier to carry. It's slimmer and lighter (about 2.2 kg) than the regular Nitro, with a calmer Shale Black finish. The NL16-71G-790D sells for <strong>Rs 1,72,499</strong>.</p>
<p>Inside is a 10-core <strong>Core i7-13620H</strong> (up to 4.9GHz), an <strong>RTX 3050 6GB</strong>, 16GB DDR5-5200 and a 512GB PCIe 4.0 SSD. The <strong>16-inch WUXGA</strong> (1920 × 1200) screen has a high refresh rate. The title says 180Hz and its spec table says 165Hz, and either is very smooth for shooters. The taller 16:10 shape is also nicer for work than the usual 15.6-inch 16:9 gaming panel.</p>
<p>Ports are good: a 10Gbps USB-C with DisplayPort and charging, two USB-A, HDMI 2.1 and Ethernet. The 53Wh battery is modest. Like the Aspire 7, the RTX 3050 here suits esports and older AAA games at 1080p better than the newest releases.</p>
