        'description' => <<<'HTML'
<p>The Nitro V 16 is the step up from the Nitro V 15. It has a bigger 16:10 screen and a much stronger processor. The ANV16-71-760Q in Obsidian Black sells for <strong>Rs 1,96,499</strong>, with lifetime free servicing from the store.</p>
<p>The <strong>Core i7-14650HX</strong> has 16 cores and 24 threads with a 5.2GHz boost, which makes this a capable "gaming and creator" laptop. Video exports, Blender renders and code builds finish far faster than on the 10-core H-series chips in cheaper Nitros. The <strong>RTX 4050 6GB</strong> runs at 85W with DLSS 3 support.</p>
<p>The <strong>16-inch WUXGA (1920 × 1200) display</strong> runs at 165Hz. It's smooth for games and gives extra vertical space for timelines and code, though at 45% NTSC it's not a colour-accurate panel. Memory is 16GB DDR5-5600 with a 512GB PCIe 4.0 SSD. It weighs about 2.5 kg, with a 59Wh battery.</p>
<p>If your budget can stretch to RTX 50-series graphics, the <a href="/products/asus-tuf-f16-fx608-i5-14450hx-rtx-5050">ASUS TUF F16 with RTX 5050</a> has 8GB of VRAM and a 100% sRGB screen for a little more.</p>
