        'description' => <<<'HTML'
<p>This Nitro V 15 pairs a 14-core <strong>Core i9-13900H</strong> (up to 5.4GHz) with an <strong>RTX 5060 8GB GDDR7</strong>. That's a big jump in gaming performance over the RTX 4050 Nitros, thanks to the newer GPU and its extra VRAM. It is listed at <strong>Rs 2,59,999</strong>, with lifetime service and software support.</p>
<p>At 1080p, the RTX 5060 runs current AAA games at high settings comfortably, and DLSS 4 multi-frame generation pushes frame rates even higher on the <strong>165Hz</strong> Full HD IPS screen. The i9 is a strong partner for streaming or video work. Memory is 16GB DDR5-4800 with a 512GB PCIe 4.0 SSD, and the ports include three USB-A, a 10Gbps USB-C, HDMI and Ethernet. It weighs 2.1 kg.</p>
<p>Should you buy it? It's a good gaming laptop, but the competition at this price is fierce. The <a href="/products/lenovo-loq-15ahp10-ryzen-7-250">Lenovo LOQ with RTX 5060</a> costs about Rs 20,000 less, and the <a href="/products/asus-tuf-a16-fa608umi-ryzen-7-260-rtx-5060">ASUS TUF A16 with RTX 5060</a> has a bigger 16-inch screen and a 70Wh battery. Choose the Nitro V 15 if you specifically want Intel's i9.</p>
