<p>The question with the base MacBook Pro is always the same: what does it give you over a MacBook Air? With the 14-inch M5 model, at <strong>Rs 3,64,999</strong> for 16GB memory and a 1TB SSD in Space Black the answer comes down to three things: a fan, a far better screen, and the ports you actually use.</p>
<p><strong>The fan</strong> means long renders, code builds and 4K exports hold their speed instead of slowing down after ten minutes the way a fanless Air does. <strong>The screen</strong> is a 14.2-inch Liquid Retina XDR panel (3024 × 1964) with 120Hz ProMotion, 1,000 nits sustained and 1,600 nits peak for HDR. If you grade video or edit photos for print, it's a different class from the Air's display. <strong>The ports</strong> are three Thunderbolt 4, HDMI, a UHS-II SD card slot, a headphone jack and MagSafe 3. Photographers can stop carrying a dongle.</p>
<p>Inside is the M5 with a 10-core CPU (4 super cores, 6 efficiency cores), a 10-core GPU and a 16-core Neural Engine. The 1TB SSD is the base storage here, which is welcome. The 12MP camera handles calls well, and the backlit Magic Keyboard has Touch ID.</p>
<p>If your work is documents, browsing and the occasional edit, the <a href="/products/macbook-air-m5-13">MacBook Air M5</a> saves you over a lakh. If you run heavier multicam timelines or 3D work, step up to the <a href="/products/macbook-pro-14-m5-pro">M5 Pro model</a> with 24GB.</p>
