<p>The Vivobook 14 X1404VAP is a simple, light laptop with one unusually smart detail for its price: the 8GB of DDR4 sits in an <strong>SO-DIMM slot</strong>, so you can drop in a bigger stick later rather than buy a new laptop. It is listed in Quiet Blue for <strong>Rs 87,000</strong>.</p>
<p>It runs Intel's <strong>Core 5 120U</strong>, a 10-core, 12-thread chip that turbos to 5.0GHz. That's plenty for Office, Google Workspace, Zoom, Canva and a busy browser. The 14-inch Full HD panel is anti-glare and TÜV Rheinland certified, and at about 1.4 kg it's easy to carry to campus or a co-working space. ASUS quotes up to 8 hours of battery from the 42Wh cell. Expect less if you keep brightness high.</p>
<p>There are two compromises. The 256GB SSD fills up quickly once you install a few apps and keep your photos locally. The screen is a basic 250-nit panel, fine indoors but dim next to a sunny window. Ports cover the essentials: two USB-A 3.2, a USB-C, a USB 2.0 and HDMI. The touchpad doubles as a NumberPad.</p>
<p>If you'd rather have 512GB of storage and a bigger screen for similar money, see the <a href="/products/asus-vivobook-15-e1504fa-ryzen-5-40">Vivobook 15 E1504FA</a>.</p>
