        'description' => <<<'HTML'
<p>The Vivobook Go 14 is ASUS's "go anywhere" budget laptop. At 1.38 kg with a 14-inch Full HD screen, it's light enough for daily commuting, and it has a <strong>backlit keyboard</strong>, which many laptops at this price skip. Our partner shop sells two versions with 8GB LPDDR5 and a 512GB SSD: <strong>Ryzen 3 30 at Rs 95,499</strong>, and <strong>Ryzen 5 40 at Rs 1,08,499</strong>.</p>
<p>The two chips are closer than the names suggest. Both have 4 cores and 8 threads. The Ryzen 5 boosts slightly higher (4.3GHz against 4.1GHz). For typing, browsing and video calls you'll barely notice the difference. What you are partly paying for is the package: the Ryzen 3 listing carries a <strong>2-year warranty plus a year of ASUS Perfect Warranty</strong> (accidental damage), while the Ryzen 5 listing comes with a free bag, mouse and mousepad.</p>
<p>Elsewhere they're the same: a 250-nit FHD anti-glare panel, Wi-Fi 6E, a 720p camera with privacy shutter, a 42Wh battery, and USB-C, USB-A, USB 2.0 and HDMI ports. Memory is soldered at 8GB.</p>
<p>Honestly, if you want the most laptop for the money, the larger <a href="/products/asus-vivobook-15-e1504fa-ryzen-5-40">Vivobook 15 E1504FA</a> has the same Ryzen 5 40 and costs less. The Go 14 wins on portability and that backlit keyboard.</p>
