<p>The CPU is a 4-core, 8-thread chip that boosts to 4.5GHz. It's efficient rather than fast, so this suits office, study and creative-lite work rather than heavy rendering. There's 16GB of DDR5 onboard plus a free SO-DIMM slot, for <strong>up to 32GB</strong> later, and a 512GB PCIe 4.0 SSD.</p>
<p>The rest is well chosen. The 14-inch WUXGA (1920 × 1200) panel is a taller 16:10 shape at 300 nits. The FHD webcam has <strong>IR face login</strong> and a privacy shutter. Two USB-C ports support charging and display output, and HDMI 2.1 drives a 4K monitor properly. At 1.46 kg it's easy to carry. The 42Wh battery is the weak point, so carry the charger on long days.</p>
