<p>At <strong>Rs 1,53,499</strong>, the TUF A15 is the cheapest dedicated-GPU gaming laptop on the shelf. Our partner shop also includes a bag, a mouse, a mousepad and lifetime service support. For a student who mostly plays Valorant, PUBG PC, CS2, Dota 2 or Minecraft, that's a lot of laptop for the money.</p>
<p>Inside is a 6-core <strong>Ryzen 7 7445HS</strong> (12 threads, up to 4.5GHz), <strong>16GB DDR5</strong> (expandable to 32GB) and a 512GB PCIe 4.0 SSD. The GPU is an <strong>RTX 3050 with 4GB</strong> of VRAM at up to 75W with Dynamic Boost. It's fine for esports titles at high frame rates, but 4GB of VRAM is tight for new AAA games, which you'll play at low to medium settings.</p>
<p>The screen is where the savings show. It runs at 144Hz with Adaptive-Sync, which is great for shooters, but it only covers about 62% of sRGB, so colours look washed out next to the LOQ's 100% sRGB panel. That matters if you also edit photos. You do get an RGB-backlit keyboard, Ethernet, HDMI 2.1, a 10Gbps USB-C with DisplayPort, and three USB-A ports. The 48Wh battery is small.</p>
<p>For roughly Rs 11,000 more, the <a href="/products/lenovo-loq-15-15ahp9-2024-ryzen-7-7445hs">Lenovo LOQ 15AHP9</a> has the same CPU with an RTX 3050 <em>6GB</em> at 95W and a far better screen. We'd stretch for it if you can.</p>
