<p>The screen is a <strong>13.3-inch 3K (2880 × 1800) OLED</strong>, Pantone-validated with 100% DCI-P3 and 550-nit HDR peaks, so text is crisp and photos look accurate. A <strong>Core i7-1355U</strong> (10 cores, up to 5.0GHz) with 16GB LPDDR5 and a <strong>1TB</strong> PCIe 4.0 SSD keeps office and browser work fast. A 63Wh battery is big for such a small laptop.</p>
<p>Despite the thinness you still get <strong>two Thunderbolt 4</strong> ports, a full-size USB-A and HDMI 2.1, so no dongles needed for a projector. The trade-offs: memory is fixed at 16GB, the panel is 60Hz, and Iris Xe graphics are only for light creative work.</p>
