<p>The 2024 Zenbook S13 keeps everything that made the original a favourite, including the 1 kg body, a stunning 3K OLED and two Thunderbolt ports, and moves to Intel's <strong>Core Ultra 7 155U</strong>. The current price is <strong>Rs 2,00,000</strong> with 16GB LPDDR5X, a <strong>1TB</strong> SSD, a 2-year global warranty and a bag, mouse and mousepad.</p>
<p>The new chip brings 12 cores and an <strong>Intel AI Boost NPU</strong>, which handles background blur, eye contact and noise cancellation on calls without draining the battery. Day-to-day speed is similar to the i7-1355U model. The real gains are efficiency and readiness for newer AI features in Windows.</p>
<p>The 13.3-inch OLED runs at 2880 × 1800 with <strong>DisplayHDR True Black 600</strong> and 100% DCI-P3, and is Pantone validated. It's one of the nicest small screens on any Windows laptop. The 63Wh battery, two Thunderbolt 4 ports, USB-A and HDMI 2.1 are all unchanged.</p>
<p>Which one to buy? If the price gap with the <a href="/products/asus-zenbook-s-13-oled-2023-i7-1355u">i7-1355U Zenbook S13</a> stays around Rs 9,000, take this newer model for the NPU and longer software runway. If you want a bigger screen, faster graphics and Wi-Fi 7, step up to the <a href="/products/asus-zenbook-14-oled-ux3405ca-2025">Zenbook 14 OLED</a>.</p>
