        'description' => <<<'HTML'
<p>This TUF F16 is an affordable RTX 50-series laptop that gets the fundamentals right. The <strong>RTX 5050 8GB</strong> runs at <strong>115W</strong> (100W plus 15W Dynamic Boost) with a <strong>MUX switch</strong>, which routes frames straight from the GPU to the screen for a few extra percent of performance. It is listed for <strong>Rs 2,02,999</strong>.</p>
<p>The <strong>Core i5-14450HX</strong> (10 cores, 16 threads, up to 4.8GHz) is a sensible match for the GPU at 1080p and 1200p. The 16-inch WUXGA (1920 × 1200) screen runs at 144Hz and covers <strong>100% sRGB</strong>, a big step up from the washed-out panels on older budget TUFs. Memory is 16GB DDR5-5600 on SO-DIMM, with a 512GB PCIe 4.0 SSD.</p>
<p>Practical touches make it easy to recommend. There's a <strong>70Wh battery</strong>, a <strong>1080p webcam</strong>, Wi-Fi 6E with Bluetooth 5.4, Ethernet, three 10Gbps USB-A ports and a USB-C with DisplayPort and charging. It weighs 2.2 kg, lighter than most 16-inch gaming laptops.</p>
<p>Spending Rs 40,000 more gets you the <a href="/products/asus-tuf-f16-fx608jhr-i7-14650hx-rtx-5050">TUF F16 FX608JHR</a>, which adds an i7, a 165Hz screen, Thunderbolt 4 and a 90Wh battery with the same GPU. For pure gaming value, this i5 model is the smarter buy.</p>
