        'description' => <<<'HTML'
<p>The FX608JHR is the "everything sensible" version of the TUF F16. It keeps the same <strong>RTX 5050 8GB at 115W</strong> as the cheaper i5 model and upgrades almost everything around it. It is listed at <strong>Rs 2,42,499</strong> with <strong>2 years of international warranty plus a year of ASUS Perfect Warranty</strong>.</p>
<p>The CPU becomes a <strong>Core i7-14650HX</strong> with 16 cores, 24 threads and a 5.2GHz boost, which makes a real difference if you stream, edit or compile. The 16-inch WUXGA panel steps up to <strong>165Hz</strong> with G-SYNC, 100% sRGB and 75% Adobe RGB. The battery grows to <strong>90Wh</strong>, the largest allowed on flights, and a <strong>Thunderbolt 4</strong> port joins the 10Gbps USB-C, three USB-A ports, HDMI 2.1 and Ethernet.</p>
<p>One detail to confirm: the title says 512GB SSD while its spec table says 1TB, so ask which you're getting.</p>
<p>Is it worth Rs 40,000 over the <a href="/products/asus-tuf-f16-fx608-i5-14450hx-rtx-5050">TUF F16 FX608 i5</a>? For gaming alone, no. The GPU is identical. For a laptop that also has to survive heavy work, long trips and three years of use, the bigger battery, faster CPU and extra warranty make a strong case. For more GPU, look at the <a href="/products/asus-tuf-a16-fa608umi-ryzen-7-260-rtx-5060">TUF A16 with RTX 5060</a>.</p>
