        'description' => <<<'HTML'
<p>If someone asks us for a Windows alternative to the MacBook Air, the Zenbook 14 OLED UX3405CA is usually the answer. It weighs 1.28 kg, has a 75Wh battery and two <strong>Thunderbolt 4</strong> ports, and runs Intel's 16-core <strong>Core Ultra 7 255H</strong> with <strong>Arc 140T</strong> graphics. That's one of the fastest integrated GPUs you can get, with AV1 encode and decode for video work.</p>
<p>The listing shows two versions, and the pricing is a little odd. Read before you choose:</p>
<ul>
<li><strong>3K (2880 × 1800) 120Hz OLED touchscreen with a 1TB SSD: Rs 2,75,999.</strong> This is the one to buy. It has the sharper, smoother screen and twice the storage.</li>
<li><strong>WUXGA (1920 × 1200) 60Hz OLED with a 512GB SSD: Rs 2,76,499.</strong> It costs slightly more for a lesser configuration. It only makes sense if the 3K model is out of stock.</li>
</ul>
<p>Both have 16GB of LPDDR5X, <strong>Wi-Fi 7</strong>, Bluetooth 5.4, an IR webcam with a privacy shutter, USB-A, HDMI 2.1, a backlit keyboard with a NumberPad touchpad, and 2 years of international warranty plus a year of ASUS Perfect Warranty. The OLED panels cover 100% DCI-P3 with True Black 500 HDR.</p>
<p>For the same CPU with a plain IPS screen and a smaller budget, see the <a href="/products/asus-vivobook-s14-s3407ca-core-ultra-7-255h">Vivobook S14 S3407CA</a>. For an AMD alternative with a touchscreen, see the <a href="/products/asus-zenbook-14-oled-um3406ga">Zenbook 14 OLED UM3406GA</a>.</p>
