        'description' => <<<'HTML'
<p>The Strix G16 G614FM is a CPU-first gaming laptop. AMD's <strong>Ryzen 9 9955HX</strong> has 16 cores, 32 threads and a 5.4GHz boost, about as much processing power as fits in a laptop. That suits gamers who also stream with CPU encoding, run game servers, render in Blender or compile large projects. It is listed in Eclipse Gray for <strong>Rs 3,88,000</strong> with a 2-year international warranty and a year of Perfect Warranty.</p>
<p>The GPU is an <strong>RTX 5060 8GB</strong> at 115W with ROG Boost. It's good at 1080p and 1600p with DLSS, but it's the limiting part at the screen's native resolution in demanding games. Speaking of the screen: a <strong>16-inch 2.5K 240Hz</strong> ROG Nebula panel with 100% DCI-P3, 3ms response and Dolby Vision. There's a <strong>MUX switch</strong>, two <strong>USB4 40Gbps</strong> ports, HDMI 2.1, Ethernet and a 90Wh battery, and it weighs 2.5 kg.</p>
<p>If gaming frame rates matter more than core count, the <a href="/products/asus-rog-strix-g16-g614pp-ryzen-9-8940hx-rtx-5070">Strix G16 G614PP with RTX 5070</a> costs about Rs 65,000 more and is the faster gaming machine. The <a href="/products/asus-rog-strix-g18-g815jpr-2025-14th-gen-i9-14900hx-rtx-5070">Strix G18 G815JPR</a> gives you an RTX 5070 and a bigger screen for less.</p>
