<p>Its direct rival on the shelf is the <a href="/products/lenovo-legion-pro-7i-2025">Lenovo Legion Pro 7i with RTX 5080</a>, which has an OLED instead of Mini LED. The Scar costs less and gives you 2TB instead of 1TB.</p>
