<p>This is the top of the mountain for gaming laptops in Nepal. The ROG Strix Scar 18 G835LX pairs NVIDIA's <strong>RTX 5090 Laptop GPU with 24GB of GDDR7</strong>, running at a full <strong>175W</strong>, with Intel's 24-core <strong>Core Ultra 9 275HX</strong>. It is listed at <strong>Rs 7,78,999</strong>, with an ROG backpack and 2 years of official warranty (including a year of ASUS Perfect Warranty).</p>
