<p>If you don't need the 24GB card, the <a href="/products/asus-rog-strix-scar-16-2025-intel-core-ultra-9-275hx-rtx-5080">Scar 16 with RTX 5080</a> saves nearly Rs 1,80,000 and is far more portable.</p>
