        'description' => <<<'HTML'
<p>The Zephyrus Duo is not a normal laptop, and it isn't priced like one. It has <strong>two 16-inch 3K OLED touchscreens</strong>. You can use them stacked, side by side, or with a detachable keyboard in front. The GX651AX sells for <strong>Rs 13,38,900</strong>, with an ROG backpack and mouse, 2 years of warranty and a year of ASUS Perfect Warranty.</p>
<p>Who is this for? Video editors who want a timeline on one screen and a preview on the other, traders and analysts watching many charts, streamers running OBS and chat alongside a game, and developers who live in split windows. Both panels are 2880 × 1800 OLED at 120Hz with 100% DCI-P3, Pantone validation and stylus support.</p>
<p>The hardware is flagship-level. It has Intel's <strong>Core Ultra 9 386H</strong> with a 50 TOPS NPU, an <strong>RTX 5090 Laptop GPU with 24GB</strong>, <strong>64GB of LPDDR5X-8533</strong> and a 1TB SSD. Connectivity includes two Thunderbolt 4 ports, HDMI 2.1, two USB-A, a UHS-II SD card reader, Wi-Fi 7 and Bluetooth 6.0. The 90Wh battery won't go far with two OLEDs and an RTX 5090. It weighs 2.82 kg.</p>
<p>If you only need one great screen, the <a href="/products/asus-rog-strix-g18-scar-g835lx-2025-core-ultra-9-275hx-rtx-5090">ROG Strix Scar 18</a> has the same RTX 5090 for well under half the price.</p>
