        'description' => <<<'HTML'
<p>The Dell Pro 15 is the most affordable Dell on the shelf at <strong>Rs 86,499</strong>. It has one feature that's unusual at this price: a <strong>120Hz</strong> 15.6-inch Full HD screen. Scrolling through long documents and web pages feels noticeably smoother than on the 60Hz panels most budget laptops use.</p>
<p>Inside is AMD's 4-core <strong>Ryzen 5 7520U</strong> (8 threads, up to 4.3GHz) with Radeon 610M graphics, 8GB of LPDDR5-5500 (onboard) and a 512GB NVMe SSD. That's comfortable for study, office suites and video calls. The anti-glare IPS panel is 250 nits, so it's best used indoors.</p>
<p>Ports are a mixed bag: a USB-A 5Gbps, a USB 2.0, a <strong>data-only</strong> USB-C, HDMI 1.4 and an SD card slot. The 41Wh battery is modest. The Carbon Black finish looks smarter than most budget plastic.</p>
<p>The 8GB of soldered memory is the long-term limit. If you need more, the <a href="/products/hp-15-fc0043nq-2024">HP 15 with 16GB</a> costs about Rs 13,500 more.</p>
