<p>The Inspiron 14 2-in-1 7440 folds back into a tablet, comes in a soft <strong>Ice Blue</strong>, and has a <strong>1TB</strong> SSD, which is rare at this price. It is listed at <strong>Rs 1,31,500</strong>.</p>
<p>It runs Intel's <strong>Core 5 120U</strong> (10 cores, 12 threads, up to 5.0GHz) with 16GB of DDR5. That's a good combination for students and home users who take notes by hand, watch a lot of video, and want plenty of room for photos and downloads. The 14-inch FHD+ (1920 × 1200) touchscreen is anti-glare at 300 nits, so it holds up better under room lights than glossy convertibles.</p>
<p>The battery is a healthy 54Wh. Ports include two 10Gbps USB ports, two 5Gbps USB ports, HDMI and a microSD slot. At 1.71 kg it's heavier than the 1.5 kg convertibles, which you'll notice in tablet mode. Note that the 1TB drive is a QLC type, so large sustained file copies slow down a little.</p>
<p>For a faster AMD chip with Copilot+ AI features in a similar body, see the <a href="/products/dell-14-plus-2-in-1-db04255-2025-ryzen-ai-7-350-16gb-1tb-14-fhd">Dell 14 Plus 2-in-1</a>.</p>
