<p>HP's basic 15-inch laptop is a familiar sight in Nepali offices and colleges, and our partner shop stocks it with AMD's 4-core <strong>Ryzen 5 7520U</strong> in two memory sizes. The <strong>15-fc0196nia with 8GB costs Rs 89,999</strong>, and the <strong>15-fc0043nq with 16GB costs Rs 99,999</strong>. Both have a 512GB NVMe SSD and a 15.6-inch Full HD anti-glare screen.</p>
<p>The memory is soldered to the board, so the choice you make at purchase is permanent. Our advice is simple: pay the extra Rs 10,000 for 16GB. It's the difference between a laptop that handles a browser full of tabs, Teams and Excel comfortably today and one that feels sluggish in a year or two.</p>
<p>Both share HP's no-nonsense design: about 1.6 kg in silver, a full-size keyboard with number pad, Radeon integrated graphics, two USB-A ports, HDMI and a USB-C that's <strong>data-only</strong> (it can't charge the laptop or drive a monitor). The 41Wh battery covers a few hours of office work. HP lists the fc0196nia with a backlit keyboard.</p>
<p>For a more powerful chip at a similar price, see the <a href="/products/hp-15-ryzen-7-7730u-8gb">HP 15 with Ryzen 7 7730U</a>. For more memory and Ethernet, look at the <a href="/products/acer-aspire-lite-15-al15-42p-ryzen-5-7430u">Acer Aspire Lite 15</a>.</p>
