<p>The OmniBook X Flip is HP's AI-era convertible. The screen folds all the way back so you can use it as a tablet, prop it up as a tent for a recipe or presentation, or sketch on it. The Core Ultra 5 226V model sells for <strong>Rs 1,52,499</strong>.</p>
<p>Intel's <strong>Core Ultra 5 226V</strong> (Lunar Lake) is built for efficiency. It has 8 cores, an NPU for Copilot+ features and <strong>Arc 130V</strong> graphics, with 16GB of LPDDR5X-8533 in the chip package. Combined with a 59Wh battery, that means long days of notes, documents and video without hunting for a socket.</p>
