<p>This is about as little as you can spend on a new Lenovo laptop in Nepal and still get an SSD, a Full HD screen and Wi-Fi 6. The IdeaPad Slim 3 14AMN8 sells for <strong>Rs 66,499</strong>. It's light at 1.37 kg and has a webcam privacy shutter, a USB-C port that charges and drives a monitor, and HDMI.</p>
<p>Be realistic about the chip, though. The <strong>AMD Athlon Silver 7120U</strong> has just <strong>two cores and two threads</strong>. It is fine for one thing at a time: typing notes, a Zoom class, YouTube, Google Classroom, email. Open Chrome with fifteen tabs alongside Teams and it will slow down. The 8GB of LPDDR5 memory is soldered, so it can't be upgraded later. The 14-inch panel is a TN type, so colours shift if you look from an angle.</p>
<p>Who should buy it? A school student who mainly writes assignments, a parent who needs something for banking and video calls, or a shop counter that runs one billing app. If your budget can reach about Rs 85,000, the 4-core <a href="/products/lenovo-ideapad-1-15amn7-2023-ryzen-5-7520u">IdeaPad 1 with Ryzen 5 7520U</a> or the <a href="/products/lenovo-ideapad-slim-3-14iru8-core-i3-1315u">IdeaPad Slim 3 with Core i3-1315U</a> will feel noticeably quicker and stay usable for longer.</p>
