<p>For under Rs 75,000, the IdeaPad Slim 3 14IRU8 gets the basics right: a 13th-gen Intel chip, a <strong>512GB</strong> SSD rather than the 256GB you see on many laptops at this price, and a 1.37 kg body that fits easily in a college bag. It is listed in Arctic Grey for <strong>Rs 74,999</strong> with genuine Windows 11 Home pre-activated.</p>
<p>The <strong>Core i3-1315U</strong> has six cores (two performance and four efficiency) and boosts to 4.5GHz, so it handles Office, browser research, Zoom and streaming without feeling sluggish. The 8GB LPDDR5 memory is soldered. That's enough for study and office work today, but keep it in mind if you expect to run heavier software later. The 47Wh battery gets most students through the morning's classes. The privacy shutter on the webcam is a small thing you'll appreciate.</p>
<p>Compared with the cheaper <a href="/products/lenovo-ideapad-slim-3-14amn8-2023">Athlon-powered Slim 3</a>, this is a big step up in everyday speed. If you want a bigger screen and a number pad for accounting work, the <a href="/products/lenovo-ideapad-slim-3-15amn8-2023">15.6-inch Slim 3 15AMN8</a> costs about Rs 12,000 more.</p>
