<p>The <strong>Ryzen 5 7520U</strong> (4 cores, 8 threads, up to 4.3GHz) is not a powerhouse, but with 16GB behind it, Teams, Outlook, a CRM in the browser and a couple of spreadsheets can stay open together. The 14-inch Full HD IPS display is anti-glare and TÜV-certified for low blue light. There's a <strong>wired Ethernet port</strong>, which IT teams love, plus full-function USB-C, two USB-A ports and HDMI.</p>
