<p>The memory setup is practical: 16GB DDR4-3200 split between soldered memory and an <strong>SO-DIMM slot</strong>, so you can upgrade later. There's also a bay for a 2.5-inch drive alongside the 512GB NVMe SSD, which is handy for a cheap terabyte of extra storage. The 15.6-inch FHD IPS screen is anti-glare, and the keyboard includes a number pad. You also get Ethernet and HDMI.</p>
<p>The battery is the catch. At 38Wh, it's small. Rapid Charge gets it to 80% in about an hour, but plan on staying near a socket. At 1.65 kg it's a laptop for a desk, not a commute. If battery life matters more than core count, compare it with the <a href="/products/lenovo-v14-g4-ryzen-5-7520u-16gb">V14 G4</a>.</p>
