<p>Most 14-inch laptops use low-power U-series chips. The V14 G5 IRL fits a <strong>Core i7-13620H</strong> instead: 10 cores (6 performance and 4 efficiency), 16 threads and a 4.9GHz boost. For developers, data analysts and engineering students who need real CPU speed but don't want a heavy gaming laptop, that's the appeal. It is listed in Iron Grey at <strong>Rs 1,37,999</strong>.</p>
<p>It comes with 16GB of DDR5-5200 and a 512GB PCIe 4.0 SSD, and weighs about 1.37–1.4 kg. Ports are business-practical: USB-C with charging and DisplayPort, USB 3.2 and USB 2.0, HDMI 1.4b and <strong>Ethernet</strong>. Wi-Fi 6 and Bluetooth 5.2 cover wireless, and the 720p webcam has a privacy shutter.</p>
<p>Lenovo saved money on the screen. It's a 14-inch FHD IPS panel at 300 nits with 45% NTSC colour, fine for code and documents but dull for photo editing. The 47Wh battery won't last as long as a U-series laptop's when you push the CPU. If colour accuracy matters to you, look at the <a href="/products/lenovo-ideapad-slim-5-14agp11-ryzen-ai-5-430">IdeaPad Slim 5 14AGP11</a> with its brighter glossy touchscreen.</p>
