<p>Students who annotate PDFs, sketch diagrams or sign documents will get real use from the pen and touch screen. The display is brighter than usual at 400 nits, though it's glossy, so watch for reflections near windows. Memory is 2 × 8GB DDR5-5600 on <strong>SO-DIMM sticks</strong>, so you can upgrade it later. The Radeon 840M graphics are among the better integrated GPUs for light creative work.</p>
<p>The 60Wh battery is larger than in most laptops at this price, charging is over USB-C, and the port selection is generous: two USB-C (10Gbps, with charging and DisplayPort 1.4), two USB-A, HDMI 2.1 and a microSD reader. The FHD webcam has an IR sensor for face login. At 1.54 kg it's a touch heavier than ultraportables. If you don't need touch or a pen, the <a href="/products/lenovo-ideapad-slim-3-15arp10-2025">IdeaPad Slim 3 15ARP10</a> saves around Rs 36,000.</p>
