        'description' => <<<'HTML'
<p>If you want to play Valorant, CS2, GTA V or Fortnite on a budget and still have a laptop that handles college work, the LOQ 15AHP9 is one of the most sensible starting points in Nepal. It is listed at <strong>Rs 1,64,499</strong>.</p>
<p>The <strong>RTX 3050 6GB</strong> here runs at a <strong>95W TGP</strong>. That's the detail to check, because the same GPU name appears on laptops that cap it at 45–65W and lose a lot of frame rate. With the 6-core <strong>Ryzen 7 7445HS</strong> (12 threads, up to 4.7GHz), expect high frame rates in esports titles at 1080p and playable medium settings in most modern AAA games, with DLSS doing the heavy lifting.</p>
<p>The 15.6-inch FHD IPS panel runs at <strong>144Hz with G-SYNC</strong> and covers 100% sRGB, so it's good for photo editing as well as games. You get 16GB DDR5-5600 in a single SO-DIMM. Adding a second matching stick for dual channel is the cheapest performance upgrade you can make. The ports are well placed: three USB-A, USB-C with 100W charging and DisplayPort, HDMI 2.1 and Ethernet, most of them at the back, which keeps cables away from your mouse hand.</p>
<p>It weighs 2.38 kg, so it's a laptop that mostly lives on a desk. For more GPU headroom in new games, the <a href="/products/lenovo-loq-15-2025">LOQ 15 with RTX 5050</a> is the next step.</p>
