<p>The unusual thing about this LOQ is the memory: <strong>24GB of DDR5</strong> (2 × 12GB) instead of the usual 16GB. For gamers who also stream, keep Discord and a browser open while playing, or edit their own clips, that extra headroom is genuinely useful. Our partner shop sells this configuration at <strong>Rs 1,74,999</strong> with a laptop bag, mouse and mousepad included.</p>
<p>The <strong>Core i5-13450HX</strong> is a 10-core, 16-thread HX chip, desktop-class silicon in a laptop that boosts to 4.6GHz. It pairs with an <strong>RTX 3050 6GB</strong> and a 15.6-inch FHD IPS screen at 144Hz with G-SYNC and 100% sRGB. That covers competitive shooters at high refresh rates, and story games at medium settings with DLSS.</p>
<p>The battery is 60Wh with Super Rapid Charge Pro, the keyboard has white backlighting and 100% anti-ghosting, and the ports are mostly at the rear: two USB-A, Ethernet, HDMI 2.1 and power. The right side has a USB-A and a USB-C with 140W charging and DisplayPort. One note: the 512GB SSD is a QLC drive, which is slower on big sustained writes. Many buyers add a second SSD for their game library. If you'd rather have a stronger GPU than more RAM, look at the <a href="/products/lenovo-loq-15-intel-i7-13650hx-rtx-4050">LOQ 15IRX9 with i7 and RTX 4050</a>.</p>
