        'description' => <<<'HTML'
<p>The LOQ 15 AX9E is the "Essential" version of Lenovo's budget gaming laptop. What makes the listing worth a look is the <strong>2-year official Lenovo Nepal warranty</strong>, double the usual cover on a gaming laptop. It's priced at <strong>Rs 1,82,499</strong> in Luna Grey.</p>
<p>Inside is the <strong>Core i5-12450HX</strong> (8 cores, 12 threads, up to 4.4GHz) with an <strong>RTX 3050 6GB</strong> running at <strong>65W TGP</strong>. That's lower than the 95W in the <a href="/products/lenovo-loq-15-15ahp9-2024-ryzen-7-7445hs">LOQ 15AHP9</a>, so expect fewer frames in demanding games. It's still comfortable for esports titles at high refresh rates, and for older or lighter AAA games at medium settings. Memory is 2 × 8GB DDR5-4800 in dual channel, with a 512GB PCIe 4.0 SSD.</p>
<p>The display is the same good LOQ panel: 15.6-inch FHD IPS, 144Hz, 100% sRGB, G-SYNC. The keyboard has white backlighting, and there's a card reader that the other LOQs lack. The USB-C port is data-only, so you can't charge from it. The battery is 57Wh.</p>
<p>Honestly, the cheaper AHP9 is the faster laptop. Choose the AX9E if the longer warranty and dual-channel memory out of the box matter more to you than raw GPU power.</p>
