<p>This LOQ is built around a CPU that feels almost too strong for a budget gaming laptop. The <strong>Core i7-13650HX</strong> has <strong>14 cores and 20 threads</strong> and boosts to 4.9GHz. If you game and also render in Blender, compile code or export long videos, it chews through those jobs. The current price is <strong>Rs 2,01,999</strong> with a bag, gaming mouse and mousepad.</p>
<p>Graphics come from an <strong>RTX 4050 6GB at 105W</strong>, with Advanced Optimus to switch between the GPU and the integrated chip and save battery on the move. In practice, it handles 1080p high settings in most games with DLSS 3 frame generation, and very high frame rates in esports titles. The 15.6-inch IPS panel is 144Hz with 100% sRGB.</p>
<p>The 60Wh battery supports Super Rapid Charge Pro, which reaches 80% in about 30 minutes. The keyboard has 1.5mm travel, white backlighting, anti-ghosting and a set of swappable keycaps. You get 16GB of DDR5-5600 on SO-DIMM and a 512GB PCIe 4.0 SSD.</p>
<p>Should you pick this or the newer <a href="/products/lenovo-loq-15-2025">LOQ 15 with RTX 5050</a>? The RTX 5050 has more VRAM (8GB) for new games. This i7 model wins on CPU-heavy work.</p>
