        'description' => <<<'HTML'
<p>Two things set this LOQ apart from its siblings: a <strong>20-core Core i7-14700HX</strong> and a <strong>1TB SSD</strong> as standard. It's on the shelf at <strong>Rs 2,34,999</strong>.</p>
<p>The i7-14700HX (8 performance and 12 efficiency cores, 28 threads, up to 5.5GHz) is one of the fastest mobile CPUs you can buy at this price. That makes this a sensible pick for gamers who also do heavy work, such as 3D rendering, code compilation, virtual machines or streaming with x264 encoding. The <strong>RTX 5050 8GB</strong> runs at 100W, enough for 1080p high settings in most new games with DLSS 4.</p>
<p>Doubling storage to 1TB means a handful of 100GB games fit without juggling installs. The rest is familiar LOQ: a 15.6-inch FHD IPS panel at 144Hz with 100% sRGB and G-SYNC, a white-backlit keyboard, a 5MP webcam with e-shutter, a 60Wh battery, and rear-mounted USB, HDMI 2.1 and Ethernet.</p>
<p>If your use is mostly gaming, the GPU matters more than the CPU. The <a href="/products/lenovo-loq-15ahp10-ryzen-7-250">LOQ 15AHP10 with RTX 5060</a> costs about Rs 5,000 more and will produce higher frame rates.</p>
