        'description' => <<<'HTML'
<p>This is the cheapest way into a Legion, and the reason to choose it over a LOQ at a similar price is the screen. The Legion 5 15IRX10 has a <strong>15.3-inch 2.5K (2560 × 1600) OLED</strong> panel at 165Hz with 100% DCI-P3, DisplayHDR True Black 600 and Dolby Vision. Dark game scenes and movies look a generation ahead of any IPS gaming laptop. It is listed for <strong>Rs 2,36,499</strong>.</p>
<p>It's also built more like a premium laptop. At <strong>1.9 kg</strong> it's noticeably lighter than the 2.4 kg LOQs, and it has an <strong>80Wh battery</strong>, Wi-Fi 7, a 24-zone RGB keyboard and a 5MP webcam. Inside are a 14-core <strong>Core i7-13650HX</strong>, an <strong>RTX 5050 8GB at 115W</strong>, 16GB DDR5 and a <strong>1TB</strong> SSD.</p>
<p>A trade-off to know about: at 2.5K, the RTX 5050 won't run demanding new games at native resolution with high settings. You'll lean on DLSS or play at 1080p-equivalent scaling, which still looks sharp on a 15.3-inch OLED. If you're a student who games, edits photos and wants something you can actually carry to class, this is a lovely all-rounder. If frame rates are all you care about, the <a href="/products/lenovo-loq-15ahp10-ryzen-7-250">LOQ with RTX 5060</a> is faster for similar money.</p>
HTML,
