        'description' => <<<'HTML'
<p>The ThinkPad L16 Gen 2 is for people who spend the whole day inside spreadsheets, ERPs and dashboards and want a bigger canvas without losing the ThinkPad keyboard. It costs <strong>Rs 2,66,499</strong>, ships with <strong>Windows 11 Pro</strong>, and has a <strong>3-year official warranty</strong>.</p>
<p>This model moves to the H-series <strong>Core Ultra 7 255H</strong>: 16 cores, 22 threads and up to 5.1GHz. It's a big jump over the U-series chips in the 14-inch ThinkPads when you're crunching data or compiling code. Its <strong>Intel Arc 140T</strong> graphics are strong for an integrated GPU and drive high-resolution external monitors smoothly. You get 16GB of DDR5-5600 (expandable to 64GB) and a 512GB PCIe 4.0 SSD.</p>
<p>The 16-inch WUXGA panel is 400 nits and anti-glare, and the full-size keyboard has a number pad, which accountants will appreciate. Connectivity matches the L14: two Thunderbolt 4 ports, three USB-A, HDMI 2.1 and Ethernet. At 1.79 kg it's portable for its size, and the 57Wh battery is reasonable. If you mostly work in one place and want something more compact, the <a href="/products/lenovo-thinkpad-l14-gen-6-2025-intel-core-ultra-7-255u">L14 Gen 6</a> is about Rs 60,000 cheaper.</p>
