        'description' => <<<'HTML'
<p>This Legion 5 is for players who care about high refresh rates. Its <strong>16-inch WQXGA IPS panel runs at 240Hz</strong>, is bright at 500 nits, covers 100% DCI-P3 and is DisplayHDR 400 certified. Competitive shooters feel noticeably smoother than on a 144Hz or 165Hz screen. It is listed in Storm Grey for <strong>Rs 3,27,499</strong>.</p>
<p>The CPU is Intel's <strong>Core Ultra 9 275HX</strong> with 24 cores and a 5.4GHz boost, the same flagship chip found in laptops costing twice as much. It comes with <strong>32GB of DDR5-5600</strong> (2 × 16GB) and a <strong>1TB</strong> SSD, so this configuration won't need upgrades for years. The <strong>RTX 5060 8GB</strong> runs at 105W. It's strong at 1080p and capable at 1600p with DLSS 4, although the 24-core CPU is clearly the star here.</p>
<p>Other highlights include Wi-Fi 7, a Thunderbolt 4 port, HDMI 2.1, a 24-zone RGB keyboard, a 5MP webcam and an 80Wh battery. It weighs about 2.45 kg.</p>
<p>Gaming is the priority, but you also stream, edit or run engineering software? This is a balanced pick. If you'd trade the 240Hz IPS for a gorgeous OLED, the <a href="/products/lenovo-legion-pro-5i-16iax10-2025-intel-core-ultra-9-275hx-rtx-5060">Legion Pro 5i</a> has the same CPU and GPU with an OLED panel.</p>
