        'description' => <<<'HTML'
<p>This Legion 5 combines the brightest panel tech Lenovo puts in its mid-range gaming laptops with a GPU that can actually drive it. A <strong>2.5K (2560 × 1600) OLED</strong> at 165Hz with 1000-nit HDR peaks, 100% DCI-P3 and Dolby Vision sits on top of an <strong>RTX 5070 8GB at 115W</strong>. It is listed in Eclipse Black for <strong>Rs 3,39,499</strong>.</p>
<p>The RTX 5070 is a meaningful step up from the RTX 5060. It handles new AAA games at the panel's native resolution with high settings and DLSS 4, and it has the tensor muscle for local AI image tools. The <strong>Core i9-14900HX</strong> (24 cores, 32 threads, up to 5.8GHz) is overkill for games alone, but it's excellent for streaming, video exports and compiling code.</p>
<p>You get a 1TB SSD and 16GB of DDR5-5600. We'd add a second 16GB stick for 32GB if you multitask heavily. Wi-Fi 7, a 24-zone RGB keyboard, HDMI 2.1 and two 10Gbps USB-C ports round it out, and our partner shop adds lifetime free servicing on top of the 1-year warranty.</p>
<p>Comparing options? The <a href="/products/lenovo-legion-5-16iax10-ultra-9-275hx-rtx-5060">Legion 5 16IAX10</a> has a 240Hz IPS screen and 32GB of RAM but a weaker GPU. The <a href="/products/lenovo-legion-pro-5-16afr10-2025-ryzen-9-9955hx-rtx-5070">Legion Pro 5 with Ryzen 9 9955HX</a> has the same RTX 5070 with a 16-inch OLED and 32GB.</p>
