        'description' => <<<'HTML'
<p>Most gaming laptops ask you to carry 2.4 kg or more. The 2026 Legion 5a Gen 11 starts at <strong>1.87 kg</strong>, has an <strong>80Wh battery</strong>, and runs AMD's new <strong>Ryzen AI 9 465</strong> with a 50 TOPS NPU. It's a gaming laptop that also works as an everyday machine you take to the office. It is listed at <strong>Rs 4,42,999</strong> with a 2-year warranty.</p>
<p>The Ryzen AI 9 465 has 10 cores and 20 threads with a 5.0GHz boost. It's more efficient than Intel's HX chips, which means longer battery life on the go and Copilot+ PC features in Windows. Graphics come from an <strong>RTX 5060 8GB at 115W</strong>. Memory is <strong>32GB DDR5-5600</strong> in dual channel with a 512GB SSD. Storage is the one spec we'd upgrade soon, because that's small for a gaming library.</p>
<p>The <strong>15.3-inch 2.5K OLED</strong> is excellent: 165Hz, 1000 nits peak, True Black 1000 and 100% DCI-P3. Two <strong>USB4 40Gbps</strong> ports, HDMI 2.1, Ethernet, Wi-Fi 7 and a <strong>5MP + IR</strong> webcam for face login make it a strong work laptop too.</p>
<p>At this price, the <a href="/products/lenovo-legion-pro-5-16afr10-2025-ryzen-9-9955hx-rtx-5070">Legion Pro 5 with RTX 5070</a> is faster for pure gaming. The 5a is for buyers who value portability and battery life just as much.</p>
