        'featured' => true,
        'description' => <<<'HTML'
<p>The Legion Pro 7i is Lenovo's flagship gaming laptop, the one reviewers reach for when they want to know how fast a laptop can get. Every version our partner shop stocks uses Intel's 24-core <strong>Core Ultra 9 275HX</strong>, <strong>32GB of DDR5-6400</strong>, a 1TB SSD and a <strong>16-inch 2560 × 1600 OLED at 240Hz</strong> with 100% DCI-P3 and True Black 1000. The difference between them is the graphics card.</p>
<ul>
<li><strong>RTX 5070 Ti 12GB (140W)</strong> – Rs 5,98,999. Excellent at 1600p in every current game. The 12GB of VRAM is a real advantage over 8GB cards.</li>
<li><strong>RTX 5080 16GB (175W, 7,680 CUDA cores)</strong> – Rs 7,18,999. The sweet spot for maxed-out settings with path tracing, plus large local AI models and heavy 3D work.</li>
<li><strong>RTX 5090 24GB</strong> – listed at Rs 5,89,499. That's below the RTX 5070 Ti listing, which looks like a pricing error on the store's side. Confirm the exact configuration and price with the shop before you pay.</li>
</ul>
<p>The cooling is what makes a laptop like this work. The Coldfront vapour chamber with liquid metal lets the RTX 5080 run at its full 175W without the fans screaming. You also get a per-key RGB keyboard, Thunderbolt 4, HDMI 2.1, 2.5Gb Ethernet, Wi-Fi 7 and a 5MP webcam. It weighs about 2.6–2.7 kg, so it's a desktop replacement you can move between rooms rather than carry every day.</p>
<p>For comparison, the <a href="/products/asus-rog-strix-scar-16-2025-intel-core-ultra-9-275hx-rtx-5080">ROG Strix Scar 16 with RTX 5080</a> is the closest rival on the shelf.</p>
