<p>It uses a <strong>TN</strong> panel at <strong>144Hz</strong>. TN looks less colourful than IPS from an angle, but it's very responsive, and BenQ adds <strong>DyAc</strong> motion-blur reduction, so enemies stay sharp during fast flicks in Valorant and CS2. <strong>Black eQualizer</strong> brightens dark corners without washing out the whole image, and Color Vibrance lets you tune saturation for visibility. FreeSync Premium is supported.</p>
