        'description' => <<<'HTML'
<p>A portable monitor turns any laptop into a two-screen workstation. That's handy in a co-working space, a hotel room or a client's office. The Dahua PM16-F201SDT adds <strong>touch</strong>, which few portable screens at this price offer. It is listed at <strong>Rs 25,499</strong>.</p>
<p>It's a 15.6-inch Full HD IPS panel with 10-point multi-touch and weighs just <strong>0.87 kg</strong>. The clever part is the connectivity. <strong>Two full-function USB-C ports</strong> carry video, touch data and power over a single cable from a compatible laptop. If you plug your charger into the monitor, it passes up to <strong>45W</strong> back to the laptop. It has 2 × 1W speakers and a 3H-hardness anti-glare surface.</p>
<p>The panel is a basic 250-nit, 45% NTSC type at 60Hz. It's fine for documents, chat and reference material, but not for colour work or fast gaming. Also check that your laptop's USB-C port supports DisplayPort output. Many budget laptops have data-only USB-C, including some on this site.</p>
