        'description' => <<<'HTML'
<p>The MSI PRO MP225V is about the least you can spend on a good new monitor in Nepal: <strong>Rs 12,300</strong>, with a <strong>2-year warranty</strong>. That's double the warranty you get on most budget screens.</p>
<p>It's a 21.45-inch Full HD <strong>VA</strong> panel. VA's strength is contrast, and at 4000:1 blacks look properly dark, so films and dark games have more depth than on a typical IPS office monitor. It refreshes at <strong>100Hz</strong> with Adaptive-Sync, which makes scrolling and cursor movement noticeably smoother than 60Hz. MSI rates it at 300 nits and 100% sRGB. Anti-flicker, low blue light and MSI's EyesErgo modes help on long days.</p>
<p>There are no built-in speakers. Audio goes out through a 3.5 mm jack. The stand tilts only, but it's VESA 100 × 100 mountable if you want an arm. As a second screen for a laptop, a home-office starter or a student's desk, it's hard to argue with. If you prefer IPS colours and viewing angles, the <a href="/products/msi-pro-mp225-22-inch-ips-100hz">MSI PRO MP225</a> costs Rs 700 more.</p>
