<p>It's a Full HD <strong>IPS</strong> panel with 178° viewing angles, 250 nits brightness and a 5 ms response time. Refresh rate tops out at <strong>75Hz</strong> with AMD FreeSync, a small step up from 60Hz. Samsung's Eye Saver Mode and flicker-free backlight help with long sessions. Inputs are HDMI 1.4 and VGA.</p>
<p>Being honest about value: you're paying for the Samsung name and the design. The <a href="/products/msi-pro-mp243l-e14-24-inch-144hz">MSI PRO MP243L</a> is bigger at 23.8 inches, much smoother at 144Hz, comes with a 2-year warranty and costs Rs 1,000 less. Choose the Samsung if you want that particular look or need to match other Samsung monitors.</p>
