        'description' => <<<'HTML'
<p>The RTX 5060 is the graphics card most people building a 1080p gaming PC in Nepal should look at first, and PNY's overclocked dual-fan version costs <strong>Rs 87,999</strong>.</p>
<p>Built on NVIDIA's Blackwell architecture, it has <strong>3,840 CUDA cores</strong> and <strong>8GB of fast GDDR7</strong> on a 128-bit bus. In practice it runs current games at 1080p high settings, and DLSS 4 with multi-frame generation pushes frame rates far higher in supported titles. That's enough for a 144–180Hz monitor in most games. It's also useful for Stable Diffusion and video encoding with NVENC.</p>
<p>It's an easy card to fit into a typical build. Total board power is just <strong>145W</strong> from one 8-pin connector, PNY recommends a <strong>550W</strong> power supply, and the compact dual-fan design suits most mid-tower cases. Outputs are three DisplayPort 2.1b and one HDMI 2.1b. Note that it runs on PCIe 5.0 <strong>x8</strong>. On older PCIe 3.0 motherboards, that can cost some performance, so it's best paired with a PCIe 4.0 or newer board.</p>
